[6568] = { en = "The Testament of Rexxar", tier = 4,
  t = "Het testament van Rexxar",
  d = "Wat weet je van illusies, $N? Want het is een illusie die je moet maken om de verdediging van de Black Flight te omzeilen.$B$BIk ken iemand die je misschien wil helpen bij je misleiding. Ze heeft ons volk vroeger geholpen, als ze vond dat de zaak het waard was.$B$BIn de Western Plaguelands vind je Myranda the Hag, een meester in illusies. Ze is verbannen uit de alliantie van Lordaeron. Reis daarheen en neem dit bericht mee.",
  o = "Breng Rexxar's Testament naar Myranda the Hag in de Western Plaguelands.",
  p = "Ik zie niet vaak iemand van de Horde in deze delen van Lordaeron. Wat heb je voor Myranda?",
  c = "<Myranda houdt het briefje vast, wacht even en glimlacht dan.>$B$BHoe gaat het met hem? Met Rexxar, bedoel ik. Ach, kom nou, kijk niet zo verward. De brief is met opzet leeg gelaten. Hij droeg de bedoelingen en gedachten van zijn maker met zich mee. Als je kijkt naar wat erin staat, is het geen wonder dat Rexxar hem zo heeft gelaten. Stel je voor dat je gevangen of gedood was en deze informatie werd ontdekt!$B$BAch, laat maar! Myranda zal je helpen, $r. Ik ben de Warchief nog een gunst of twee verschuldigd.$B$B<Myranda glimlacht.>$b",
  g = { {"verdediging", "defense"}, {"omzeilen", "to get around, circumvent"}, {"misleiding", "deception"}, {"verbannen", "exiled"}, {"meester", "master"}, {"briefje", "note"}, {"verward", "confused"}, {"met opzet", "on purpose"}, {"bedoelingen", "intentions"}, {"stel je voor", "imagine"}, {"laat maar", "never mind"}, {"gunst", "favor"}, {"verschuldigd", "owed"} },
},

[8957] = { en = "Anthion's Parting Words", tier = 4,
  t = "De afscheidswoorden van Anthion",
  d = "De ziel van Valthalak zat in deze amulet opgesloten. Uit hebzucht hebben we hem dom genoeg in drie delen gesplitst. We wisten niet welke vloek ons te wachten stond.$B$BDe enige manier om de spreuk van Valthalak te stoppen, is de amulet weer in elkaar te zetten. Ga terug naar Mokvar en zeg hem dat Bodley zijn enige hoop is om de andere stukken te vinden. Praat met hem over de beloningen die je hebt afgesproken.$B$BIk zal voor één keer in vrede rusten. Ik wens je veel geluk; je zult elk beetje ervan nodig hebben!",
  o = "Keer terug naar Mokvar in Orgrimmar met een set Boots of Elements, Kilt of Elements en Pauldrons of Elements.",
  p = "Je bent terug, $N. Je moet me alles vertellen over wat je hebt ontdekt. Maar laten we eerst je beloning regelen.",
  c = "Ik kan niet geloven dat onze levens zo goed als verloren zijn, allemaal door een stom medaillon! En weet je zeker dat Anthion Bodley noemde?$B$BNou, je hebt je werk gedaan, dus laten we je beloning maar regelen.",
  g = { {"ziel", "soul"}, {"opgesloten", "stored, locked up (opsluiten)"}, {"hebzucht", "greed"}, {"dom genoeg", "foolishly"}, {"gesplitst", "split (splitsen)"}, {"vloek", "curse"}, {"te wachten stond", "lay in store, awaited"}, {"spreuk", "spell"}, {"in elkaar te zetten", "to put together"}, {"afgesproken", "arranged (afspreken)"}, {"in vrede rusten", "rest in peace"}, {"zo goed als verloren", "all but forfeit"}, {"stom", "stupid"} },
},

