[9032] = { en = "Bodleys Unfortunate Fate", tier = 4,
  t = "Het ongelukkige lot van Bodley",
  d = "Zat de ziel van Valthalak in het medaillon? Dan is het geen wonder dat het door zo'n sterke vloek werd beschermd.$B$BBodley vinden is een beetje een probleem. Het laatste wat ik van hem hoorde, was dat hij zich klaarmaakte om terug te gaan naar Blackrock Spire. Daarna heeft niemand meer iets van hem gehoord.$B$BZoek hem in Blackrock Mountain, al ben ik bang dat hij nu waarschijnlijk dood is. Ik raad je aan het apparaat van de goblin mee te nemen, vriend.",
  o = "Reis naar Blackrock Mountain en gebruik de Extra-Dimensional Ghost Revealer om Bodley bij Blackrock Spire te vinden.",
  c = "Ik ben zo blij dat je me kunt zien. Eindelijk iemand om mee te praten!$B$BWil je ons helpen, $N? Wil je helpen het kwaad dat we hebben gedaan ongedaan te maken en alles weer recht te zetten? Als het waar is dat je het Top Piece of Lord Valthalak's Amulet al hebt, dan kan ik je denk ik de goede kant op wijzen om de andere twee delen te krijgen. Dan kun je ze weer samenvoegen en hier een einde aan maken.$B$BO, trouwens, hallo, mijn naam is Bodley. Leuk je te ontmoeten!",
  g = { {"ongelukkige", "unfortunate"}, {"lot", "fate"}, {"ziel", "soul"}, {"vloek", "curse"}, {"klaarmaakte", "was getting ready (zich klaarmaken)"}, {"waarschijnlijk", "probably"}, {"raad je aan", "suggest to you (aanraden)"}, {"apparaat", "device"}, {"kwaad", "wrong, evil"}, {"ongedaan te maken", "to undo"}, {"recht te zetten", "to put right"}, {"de goede kant op wijzen", "point in the right direction"}, {"samenvoegen", "to reunite, join together"} },
},

})

